const WEEKDAY_NAMES: L<Record<string, string>> = {
  en: { Mon: "Monday", Tue: "Tuesday", Wed: "Wednesday", Thu: "Thursday", Fri: "Friday", Sat: "Saturday", Sun: "Sunday" },
  bn: { Mon: "সোমবার", Tue: "মঙ্গলবার", Wed: "বুধবার", Thu: "বৃহস্পতিবার", Fri: "শুক্রবার", Sat: "শনিবার", Sun: "রবিবার" },
  ar: { Mon: "الاثنين", Tue: "الثلاثاء", Wed: "الأربعاء", Thu: "الخميس", Fri: "الجمعة", Sat: "السبت", Sun: "الأحد" },
  es: { Mon: "lunes", Tue: "martes", Wed: "miércoles", Thu: "jueves", Fri: "viernes", Sat: "sábado", Sun: "domingo" },
};

export function bookingConfirmation(lang: Lang, b: { site: string; weekday: string; date: string; time: string; distanceMi: number; crewSpeaks: boolean }): string {
  const day = WEEKDAY_NAMES[lang][b.weekday] ?? b.weekday;
  const walk = Math.max(1, Math.round((b.distanceMi / 3) * 60));
  switch (lang) {
    case "bn": return `আপনার জায়গা ঠিক হয়েছে: ${day}, ${b.date}, ${b.time}-এ ${b.site}। আপনার বাসা থেকে প্রায় ${walk} মিনিট হাঁটা পথ।${b.crewSpeaks ? " টিমে বাংলা বলতে পারেন এমন কেউ থাকবেন।" : ""} সব ওষুধের বোতল সঙ্গে আনবেন।`;
    case "ar": return `تم حجز موعدك: ${day} ${b.date} الساعة ${b.time} في ${b.site}. حوالي ${walk} دقيقة سيرًا من منزلك.${b.crewSpeaks ? " سيكون في الفريق من يتحدث العربية." : ""} يرجى إحضار جميع علب الأدوية.`;
    case "es": return `Su cita está reservada: ${day} ${b.date} a las ${b.time} en ${b.site}. Unos ${walk} minutos a pie desde su casa.${b.crewSpeaks ? " Alguien del equipo habla español." : ""} Traiga todos sus frascos de medicinas.`;
    default: return `You're booked: ${day} ${b.date} at ${b.time}, ${b.site}. About a ${walk}-minute walk from home.${b.crewSpeaks ? " Someone on the crew speaks your language." : ""} Please bring all your pill bottles.`;
  }
}
